      "attack_scenario": "An admin user calls the `updateTeamLeaders` Server Action directly via HTTP POST with a `memberIds` array containing a `supabase_auth_user_id` that has no corresponding row in `member_team_relations` for the target team, thereby designating a non-member as team leader and triggering incorrect Discord role assignment for that user.",
      "checklist_id": "PROP-stem-system-pre-010"
    },
    "text": "Team leader must be a current member of the team before being designated as leader.",
    "assertion": "forall req: setLeader(req) => pre(exists(member_team_relations, req.member_id, req.team_id))",
    "covers": "SG-019",
    "severity": "LOW",
    "type": "pre-condition"
  }
}

